SELECT sp.id, sp.create_user_name AS createUserName, sp.create_time AS createTime, sp.supplier_id AS supplierId, sp.current_phase AS currentPhase, sp.target_phase AS targetPhase, sp.current_grade_id AS currentGradeId, sp.target_grade_id AS targetGradeId, sp.approve_status AS approveStatus, sp.description , su.name AS supplierName, su.code AS supplierCode, su.category_id AS categoryId, su.category_name AS categoryName, sp.approve_user_id as approveUserId, sp.approve_user_name as approveUserName, sp.approve_time as approveTime FROM supplier_phase sp INNER JOIN supplier su ON su.id=sp.supplier_id and su.is_deleted = false WHERE ${params.sqlMap.default} and sp.is_deleted=false
AND su.name ILIKE concat('%', #{params.name}::text ,'%')
AND su.category_id IN
#{categoryId}
AND sp.approve_status IN
#{approveStatus}
AND sp.approve_status IN
#{approveStatus}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sp.create_time DESC
